e-picture{position:absolute;inset:0;background-size:cover;background-position:center}.scene-picture img{width:100%;height:100%;object-fit:cover;display:block}.scene-picture.contain img{object-fit:contain;background:linear-gradient(#b6d5dc,#f5dbad)}.scene-overlay{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,transparent 65%,#09274520)}.scene-hotspot{position:absolute;z-index:3;transform:translate(-50%,-50%);width:49px;height:49px;border-radius:50%;border:3px solid white;background:#147cff4d;box-shadow:0 0 0 5px #6fc6ff85,0 0 22px 8px #3ba9ffd6;animation:glow 1.7s ease-in-out infinite;transition:transform .15s}.scene-hotspot:hover{transform:translate(-50%,-50%) scale(1.19);background:#ffe4a185}.scene-hotspot:disabled{opacity:1}.scene-hotspot.correct{background:#36df71b8;box-shadow:0 0 0 6px #a8f0c4}.scene-hotspot.wrong{background:#f45c4bba;box-shadow:0 0 0 6px #fbbaba}.scene-hotspot span{position:absolute;clip-path:inset(50%);width:1px;height:1px}@keyframes glow{50%{box-shadow:0 0 0 8px #a1e3ff66,0 0 30px 12px #1689f5bb}}.scene-caption{position:absolute;z-index:2;bottom:12px;right:10px;padding:6px 12px;border:3px ridge #edc06a;border-radius:9px;background:#fff0cfec;color:#66441c;font:800 11px Georgia,serif}.card-tray{display:flex;gap:9px;align-items:stretch;justify-content:center;flex-wrap:wrap;min-height:92px;margin:13px 0 0;padding:13px;background:linear-gradient(#fff1cd,#f3c98b);border:5px ridge #dcaa57;border-radius:15px;box-shadow:0 4px 0 #8d5b2d}.tray-heading{width:100%;text-align:center;font:900 13px Georgia,serif;color:#6c3f17}.pick-card{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:5px;min-width:90px;max-width:240px;flex:1 1 110px;border:3px ridge #c99244;background:linear-gradient(#fff8df,#f6d391);border-radius:12px;padding:9px 7px;text-align:center;color:#312113;font:800 12px/1.25 Georgia,serif;box-shadow:0 3px 0 #8f5c24;min-height:58px;transition:transform .12s}.pick-card img{max-height:7